update public.learning_paths
set
  title = 'Ensemble Participation',
  goal = 'Ensemble Participation',
  summary = 'Ensemble Participation is a recurring undergraduate music requirement in which students perform in choir, orchestra, band, jazz, chamber, or other approved ensembles. The course develops musicianship through rehearsal discipline, listening, stylistic preparation, conductor response, peer collaboration, and public performance. This course trains students to function as prepared, responsive, and ethical ensemble musicians who can tune, blend, read, lead, follow, rehearse independently, perform across styles, and reflect on their growth.',
  data = $enspjson${"slug": "ensemble-participation", "title": "Ensemble Participation", "description": "Ensemble Participation is a recurring undergraduate music requirement in which students perform in choir, orchestra, band, jazz, chamber, or other approved ensembles. The course develops musicianship through rehearsal discipline, listening, stylistic preparation, conductor response, peer collaboration, and public performance. This course trains students to function as prepared, responsive, and ethical ensemble musicians who can tune, blend, read, lead, follow, rehearse independently, perform across styles, and reflect on their growth.", "topics": [{"id": "ab0c11be-a8b1-4df2-a1a6-77afd54bbf31", "type": "topic", "title": "Ensemble Etiquette and Protocol", "description": "This section establishes ensemble membership as professional practice. Students learn that preparation, reliability, respect, and communication are musical skills, not merely behavioral rules.", "children": [{"id": "cd3b9d83-4f11-4621-b5c9-5e777324675f", "type": "subtopic", "title": "Preparation before rehearsal", "children": [{"id": "f186caf4-6b76-4b1a-adac-c6a81a69eac5", "type": "concept", "title": "Part marking"}, {"id": "6bc86c09-7124-4228-b61d-1fdf3e8ede38", "type": "concept", "title": "Listening and score study"}, {"id": "dd7e635a-1790-4df1-8d4b-086df5124a44", "type": "concept", "title": "Technical practice and problem spots"}], "description": "The point is to arrive ready to contribute rather than learn the part for the first time in the room."}, {"id": "22849c37-71df-4bb9-abb4-bf078730d8d8", "type": "subtopic", "title": "Rehearsal behavior", "children": [{"id": "71321614-0307-480a-a7b2-32e8392f1570", "type": "concept", "title": "Punctuality and attendance"}, {"id": "fd344461-2af3-44e4-b343-7ae03636c87e", "type": "concept", "title": "Device and talking norms"}, {"id": "0f63feed-adbc-4093-a962-dcb56b7de61e", "type": "concept", "title": "Readiness between repetitions"}], "description": "Students learn the habits that keep rehearsal efficient, focused, and respectful."}, {"id": "cba6eecb-3e8f-454b-9511-32f659663cd0", "type": "subtopic", "title": "Communication and accountability", "children": [{"id": "6ef54587-d0e3-4d8b-a8cd-1779eb6f53bd", "type": "concept", "title": "Absence reporting"}, {"id": "1516b4a2-036a-4e41-a2ae-ef30da7293c5", "type": "concept", "title": "Part questions"}, {"id": "40441908-4015-4d01-ac22-49271b32bf82", "type": "concept", "title": "Respectful feedback channels"}], "description": "Ensembles depend on clear, timely communication among players, section leaders, conductors, and staff."}, {"id": "f95b4f39-6780-4f4a-9369-a72f29e11654", "type": "subtopic", "title": "Professional culture and inclusion", "children": [{"id": "363eac08-bdbd-4edb-af9a-f372012cf23d", "type": "concept", "title": "Collegiality"}, {"id": "cfe381f8-92dd-4a2b-b9b9-95e52839ea7f", "type": "concept", "title": "Equity and access"}, {"id": "3c9cad6f-9e0d-4d5c-b4a9-88f93ee57c79", "type": "concept", "title": "Shared responsibility for morale"}], "description": "The goal is to build an ensemble room where high standards and belonging reinforce each other."}]}, {"id": "6c4510d5-bbf4-4d65-9bd1-9dd3369b8de9", "type": "topic", "title": "Following a Conductor", "description": "Students learn to translate gesture into sound. The conductor's beat, breath, cue, and body language become shared musical information for the ensemble.", "children": [{"id": "cfae49b6-0a64-4d39-94b9-7c6fdb02318a", "type": "subtopic", "title": "Beat patterns and tempo response", "children": [{"id": "0c518f7c-abdb-4636-a2f7-023bcdc13817", "type": "concept", "title": "Two, three, and four patterns"}, {"id": "7b6339d1-c23f-420c-9377-2ea65fd4d226", "type": "concept", "title": "Subdivision"}, {"id": "96dc16ca-0b86-4db9-ac78-11301c401930", "type": "concept", "title": "Tempo changes"}], "description": "Students build fluency with common meters and learn to react without lag."}, {"id": "080749b0-0ef4-4001-af77-cc9e31efabc3", "type": "subtopic", "title": "Cues, releases, and cutoffs", "children": [{"id": "b7cb38c5-abda-46d9-beb7-ca35d441b70b", "type": "concept", "title": "Preparatory gestures"}, {"id": "2f34eafc-9315-48a6-8341-c71f9584e3cd", "type": "concept", "title": "Eye contact"}, {"id": "acb1a783-f2fb-4858-a99e-503950a29ac4", "type": "concept", "title": "Breath and cutoff shapes"}], "description": "The point is to enter and release as a unified ensemble."}, {"id": "9b6e8e00-3f35-4c88-ab9c-9f02565f6f67", "type": "subtopic", "title": "Expressive gesture", "children": [{"id": "a6c736ec-39e1-437f-bbd7-b1850a575508", "type": "concept", "title": "Dynamics"}, {"id": "66919208-a175-4376-8cfb-cfffefd5a7d7", "type": "concept", "title": "Articulation"}, {"id": "aa9b9258-7a63-4249-a6fe-cf3e87fcc947", "type": "concept", "title": "Phrase direction"}], "description": "Students learn to read more than time: gesture can communicate character, weight, articulation, and phrase."}, {"id": "e07e4cfa-8f81-4ee3-93d5-068fe0546b3d", "type": "subtopic", "title": "Player responsibility", "children": [{"id": "a297dce8-ce53-484d-842b-dd5be483bd66", "type": "concept", "title": "Peripheral vision"}, {"id": "16d5755c-413e-413c-9a23-7dbd56abefb3", "type": "concept", "title": "Internal pulse"}, {"id": "b7790821-e795-4af3-9b2c-0ffb14488730", "type": "concept", "title": "Recovering after missed cues"}], "description": "Following does not mean passivity. Students learn when to watch, listen, lead, and recover."}]}, {"id": "a92ac5b5-ac1e-42bf-b657-9f8b383dcef4", "type": "topic", "title": "Blend and Balance", "description": "This section trains ensemble listening. Students learn to shape their own sound in relation to section, texture, register, harmony, and musical role.", "children": [{"id": "9b141050-131b-4bfa-a898-c6d1294460f6", "type": "subtopic", "title": "Tone matching", "children": [{"id": "833c5eb3-5aa9-48d2-bf88-22ee57f3eda7", "type": "concept", "title": "Vowel and timbre alignment"}, {"id": "e8aa79d8-516d-4a44-a659-d5f21af65123", "type": "concept", "title": "Instrumental color"}, {"id": "08c024e9-64be-4db3-be34-a78c2cac4c63", "type": "concept", "title": "Attack and release matching"}], "description": "Students learn to adjust color and resonance so individual sound supports the group."}, {"id": "a978c02f-2535-41ab-85d1-b9d09d2a97cd", "type": "subtopic", "title": "Dynamic hierarchy", "children": [{"id": "6687e8b6-b2eb-4c59-a361-0c41433f58f3", "type": "concept", "title": "Melody and accompaniment"}, {"id": "c1c073c6-8ee7-46b7-b915-d87b731e259e", "type": "concept", "title": "Inner voices"}, {"id": "e3c0dc7e-059f-4b70-a1fa-4ab653e85be8", "type": "concept", "title": "Bass and harmonic foundation"}], "description": "The goal is to understand who has primary, secondary, or background material at any moment."}, {"id": "0e8c7c11-085d-4dde-8c04-8cfa8f5447c7", "type": "subtopic", "title": "Texture and orchestration", "children": [{"id": "470298b4-0493-4468-bd64-c52bac907e3f", "type": "concept", "title": "Register awareness"}, {"id": "a6b881ee-d3d4-4588-92ce-d00e3858b6d1", "type": "concept", "title": "Doublings"}, {"id": "358705e2-d37a-4796-a360-191e98aa9941", "type": "concept", "title": "Transparent versus dense textures"}], "description": "Students listen across the score rather than only within their own part."}, {"id": "79b686c1-540b-45e4-97f2-909bd6bae143", "type": "subtopic", "title": "Chamber listening in large ensembles", "children": [{"id": "0fbe3956-dca3-4e62-8b93-e8fd0326ed88", "type": "concept", "title": "Section-to-section balance"}, {"id": "5ae87e1c-6814-4068-bec5-1ac4bd1ecafa", "type": "concept", "title": "Principal/section relationships"}, {"id": "256d5954-dafd-4304-8b44-4c9205463c9f", "type": "concept", "title": "Listening across distance"}], "description": "Even large ensembles require small-group awareness."}]}, {"id": "e32533e4-c0b0-4537-adec-7c9ae90494e1", "type": "topic", "title": "Intonation in Ensemble", "description": "Students develop practical tuning skills for real performance contexts. Intonation becomes a responsive, harmonic, and stylistic practice rather than a fixed tuner reading.", "children": [{"id": "98c480ac-2ffe-4417-8f61-2856deaf9eb5", "type": "subtopic", "title": "Reference pitch and tuning process", "children": [{"id": "1e075ed1-5ff9-4753-9fe1-8a63ad1d7c2a", "type": "concept", "title": "Tuning notes"}, {"id": "9c21b7b7-1399-4b09-a020-e68b2324f649", "type": "concept", "title": "Temperature and instrument factors"}, {"id": "4e926fff-a995-4050-835d-addd7f2a6605", "type": "concept", "title": "Vocal and instrumental warmup"}], "description": "Students learn how ensembles establish and maintain pitch centers."}, {"id": "2e362515-c2f9-4664-b6fa-f2306cc636e1", "type": "subtopic", "title": "Intervals and chord function", "children": [{"id": "6613f2b7-ccf1-42dd-892a-12419980eaf1", "type": "concept", "title": "Unisons and octaves"}, {"id": "ae608bd8-1de4-4e2e-8423-01fd004fac4e", "type": "concept", "title": "Thirds, fifths, and leading tones"}, {"id": "f8d10e02-b33e-4587-a8e3-98e44ce728fb", "type": "concept", "title": "Cadential tuning"}], "description": "The point is to tune according to harmonic role and interval tendency."}, {"id": "d6689e4c-ccf0-4ede-8df0-59e048f00dc7", "type": "subtopic", "title": "Listening and adjustment", "children": [{"id": "d4c543b8-8d0e-4772-8a7a-4708cc4616c5", "type": "concept", "title": "Beats and waves"}, {"id": "d7f00d8d-1351-4b2a-9ca9-da73ff18b1dc", "type": "concept", "title": "Matching vibrato and vowel"}, {"id": "02372d3c-8dea-458d-bc21-dbb343b2432f", "type": "concept", "title": "Adjusting without overcorrecting"}], "description": "Students practice identifying whether they are high, low, covered, or exposed."}, {"id": "9608d5fa-0e02-440c-a36f-6cc97353686f", "type": "subtopic", "title": "Style and tuning systems", "children": [{"id": "c547d99e-281e-4afe-a029-934c286d7902", "type": "concept", "title": "Equal temperament"}, {"id": "a5b6a0b0-5d23-44e7-848f-71a0b6ee0ddb", "type": "concept", "title": "Just intonation tendencies"}, {"id": "ef2b37fa-cfbc-4a70-b9bf-35894a7be83c", "type": "concept", "title": "Historical and contemporary practices"}], "description": "Advanced ensemble work requires awareness that tuning expectations vary by repertoire."}]}, {"id": "0acf3c9c-0557-48ef-91d0-fe897c9a3e42", "type": "topic", "title": "Rhythmic Precision", "description": "This section develops shared time. Students learn that rhythmic accuracy includes pulse, subdivision, articulation, ensemble releases, groove, and responsiveness.", "children": [{"id": "705d93a0-51ae-4a67-864e-dc577f54aa5b", "type": "subtopic", "title": "Pulse and subdivision", "children": [{"id": "e50d564a-ad45-4462-b121-53301c6464d9", "type": "concept", "title": "Counting systems"}, {"id": "35c0034c-3a36-4934-acfb-0bad2c2d69a5", "type": "concept", "title": "Subdividing rests"}, {"id": "7d6330d6-8e80-49ad-9127-46ec54365f20", "type": "concept", "title": "Tempo stability"}], "description": "Students strengthen the internal clock needed for ensemble independence."}, {"id": "99c01774-f630-4fd3-bbff-511c77e69264", "type": "subtopic", "title": "Articulation alignment", "children": [{"id": "1df1d84a-dd68-46a4-afe0-2de18d005ffe", "type": "concept", "title": "Attacks"}, {"id": "e9663621-f15c-4d46-826d-b2049f12dace", "type": "concept", "title": "Note lengths"}, {"id": "2bd81d94-37be-4aab-a394-d147798a158d", "type": "concept", "title": "Releases"}], "description": "Rhythm becomes audible through the beginnings, shapes, and ends of notes."}, {"id": "d344779f-38a2-4842-a354-fcf18095be8a", "type": "subtopic", "title": "Complex rhythm and meter", "children": [{"id": "180dcb77-7fb0-42ce-9cad-cef9e25c5209", "type": "concept", "title": "Syncopation"}, {"id": "3895de18-f982-44d1-bb18-73f1379321e7", "type": "concept", "title": "Mixed meter"}, {"id": "19fcea2d-fb01-44b4-a7e7-6125aab76dc1", "type": "concept", "title": "Polyrhythm and cross-rhythm"}], "description": "The goal is to approach challenging notation calmly and systematically."}, {"id": "a0f59024-ae41-4e4f-b923-2583cf510a75", "type": "subtopic", "title": "Groove and style", "children": [{"id": "29670c73-c950-4242-867c-1423ac1e8dda", "type": "concept", "title": "Swing and backbeat"}, {"id": "7deecff6-fcee-43c6-a3ba-ad7d4141f121", "type": "concept", "title": "Dance rhythm"}, {"id": "bf8404f3-0792-4e0a-abc0-4c5f80c67802", "type": "concept", "title": "Rubato and flexible time"}], "description": "Precision is not mechanical sameness. Students learn how feel changes across styles."}]}, {"id": "1d818558-bd1e-4cca-98f8-0fe8e40efd4d", "type": "topic", "title": "Sight-Reading in Ensemble", "description": "Sight-reading prepares students to function in auditions, rehearsals, church jobs, sessions, and professional ensembles. The emphasis is quick comprehension and reliable recovery.", "children": [{"id": "5b8b8546-0ce8-4485-aa1b-9f7c9d15b37f", "type": "subtopic", "title": "Pre-reading scan", "children": [{"id": "0a2ac27c-632e-40f7-b565-5992f3281e50", "type": "concept", "title": "Key and meter"}, {"id": "4c32b1f7-b379-402f-928e-288ba5afa0bd", "type": "concept", "title": "Tempo and style markings"}, {"id": "af4ed5f7-ff89-415d-9568-329ae946be4a", "type": "concept", "title": "Road maps, repeats, and cues"}], "description": "Students learn what to notice before the first note."}, {"id": "a261ae7f-0d27-401d-83d2-5734602d839b", "type": "subtopic", "title": "Rhythm-first strategies", "children": [{"id": "005099f4-8682-4b0c-a65f-0b6bde985ed0", "type": "concept", "title": "Counting rests"}, {"id": "5aadd46b-16c5-4a7c-8ace-0cef4d0390bc", "type": "concept", "title": "Prioritizing entrances"}, {"id": "4cacbec9-881a-4fcc-8abe-5e11436941e8", "type": "concept", "title": "Maintaining pulse"}], "description": "The point is to keep time and form intact even when pitch or detail is imperfect."}, {"id": "19870f57-3e4b-432c-afe7-77025a9b2f98", "type": "subtopic", "title": "Pitch and pattern recognition", "children": [{"id": "9f05a5fc-4644-4649-97f2-0f229a0cb432", "type": "concept", "title": "Scales and arpeggios"}, {"id": "400c5b4c-fbda-4a2c-b830-ef0c02ceeccd", "type": "concept", "title": "Sequences"}, {"id": "16fab142-d596-484c-bf8b-7d7e9d672e2c", "type": "concept", "title": "Common harmonic patterns"}], "description": "Students learn to read in chunks rather than note by note."}, {"id": "1020e64c-2132-4ea4-b594-7e851d6e6726", "type": "subtopic", "title": "Recovery and ensemble awareness", "children": [{"id": "32748fcc-4a7e-4116-82cd-051928be6c5b", "type": "concept", "title": "Listening for landmarks"}, {"id": "6521c279-b4fb-46a9-92df-45372cc1bdc7", "type": "concept", "title": "Re-entering after errors"}, {"id": "5cdc7332-0a9e-4df3-b6de-7f87457e3be6", "type": "concept", "title": "Watching conductor and section"}], "description": "Strong sight-readers recover quickly and stay connected to the group."}]}, {"id": "179aad3e-f436-4126-be58-5fd72f51146b", "type": "topic", "title": "Sectional Rehearsals", "description": "Sectionals teach students to diagnose problems and rehearse efficiently without always relying on the conductor. They build leadership, independence, and shared accountability.", "children": [{"id": "271632ff-0a9f-46cb-bcf3-e289bf03ca80", "type": "subtopic", "title": "Setting sectional goals", "children": [{"id": "076862bc-1094-4f89-8f92-192c9993e395", "type": "concept", "title": "Pitch and rhythm targets"}, {"id": "b191a4da-95fb-4dfd-9409-8120c8faaf5a", "type": "concept", "title": "Balance issues"}, {"id": "da1c27a5-d064-4ccb-a651-92286c36929c", "type": "concept", "title": "Difficult transitions"}], "description": "Students learn to choose priorities that matter musically and technically."}, {"id": "d831cbf4-4b3c-4f6d-8c72-4b0c7882ff02", "type": "subtopic", "title": "Section leadership", "children": [{"id": "cc6ebcc4-db18-450f-b1e4-a0f6242d8ac7", "type": "concept", "title": "Principal responsibilities"}, {"id": "bd1703ae-1143-4cc3-93ee-b71a501fc118", "type": "concept", "title": "Constructive language"}, {"id": "837571b3-5ec2-4977-bf76-66f70c9564ed", "type": "concept", "title": "Time management"}], "description": "The goal is to lead peers clearly without turning rehearsal into criticism."}, {"id": "992e95e2-7289-49fe-b2fd-0e2588968b1b", "type": "subtopic", "title": "Rehearsal techniques", "children": [{"id": "bd81a902-4f5e-495c-be45-c9ac5f504778", "type": "concept", "title": "Slow practice"}, {"id": "139931d3-1c55-4325-a41c-9c7110f97a64", "type": "concept", "title": "Looping small units"}, {"id": "7aafe28e-a716-463e-bd97-72380c4e4264", "type": "concept", "title": "Layering rhythm, pitch, and articulation"}], "description": "Students practice tools that make repetition productive."}, {"id": "c8e292de-7832-4a93-85a4-35cdae646fa8", "type": "subtopic", "title": "Reporting and reintegration", "children": [{"id": "8feabae4-8844-457e-ba5d-89bfe615bf0f", "type": "concept", "title": "Marking decisions"}, {"id": "d2707e74-8e61-421c-96f5-14f618f2220f", "type": "concept", "title": "Questions for conductor"}, {"id": "d7ab9eb4-6b0d-4c54-adae-d4e60f859bcb", "type": "concept", "title": "Testing sectional fixes in context"}], "description": "Sectional work must return to the full ensemble with clarity."}]}, {"id": "e7eb3d55-9374-4dd3-8f4e-0af8d3c08527", "type": "topic", "title": "Repertoire Across Styles", "description": "This section broadens ensemble musicianship beyond one tradition. Students learn how style, history, notation, language, and cultural context shape performance choices.", "children": [{"id": "60b51427-c4fe-427b-9a3b-9dc211abf87a", "type": "subtopic", "title": "Historical style", "children": [{"id": "2238f6e1-9602-4b7a-a8b4-37f233de0b48", "type": "concept", "title": "Baroque and Classical conventions"}, {"id": "e0781921-96e9-4628-b4ec-ff8f63796465", "type": "concept", "title": "Romantic phrasing"}, {"id": "4040c371-8963-4f87-a171-4205f478b2df", "type": "concept", "title": "Modern and contemporary notation"}], "description": "Students connect musical choices to period, genre, and performance practice."}, {"id": "a61e9a02-b212-43db-9920-66406fcb4b73", "type": "subtopic", "title": "Vocal and instrumental idioms", "children": [{"id": "1a5482ef-6c51-48c5-b950-abc8aa6fec78", "type": "concept", "title": "Choral diction"}, {"id": "6ab93570-6283-48d9-a8e8-0221f89424b9", "type": "concept", "title": "Wind and orchestral articulation"}, {"id": "3235740f-fc7f-4a9a-b258-0cfbb5b37ecf", "type": "concept", "title": "Chamber music roles"}], "description": "Different ensembles require different approaches to breath, articulation, text, and sound."}, {"id": "500ded27-24ca-4cfe-a95a-50835d27cdc1", "type": "subtopic", "title": "Jazz, popular, and global styles", "children": [{"id": "c0dea3ca-17b6-41d8-896d-c386b668b169", "type": "concept", "title": "Swing and groove"}, {"id": "260f6125-f86c-4be9-8efc-550a43154a6b", "type": "concept", "title": "Lead sheets and charts"}, {"id": "967399cd-7149-4e14-b758-c5444eb9958c", "type": "concept", "title": "Cultural context and respect"}], "description": "The point is to avoid treating all ensemble music with the same classical assumptions."}, {"id": "482636d3-e64d-45c8-aaa7-0dbd73bb6012", "type": "subtopic", "title": "Listening as research", "children": [{"id": "ce97083f-dd94-419f-873f-962450aeab85", "type": "concept", "title": "Comparative listening"}, {"id": "b3d8f193-9268-480d-8786-5e364b83c356", "type": "concept", "title": "Style annotations"}, {"id": "34e88208-d46d-4fd7-8791-f84967cd88f5", "type": "concept", "title": "Avoiding imitation without analysis"}], "description": "Students learn to use recordings as references, not as shortcuts."}]}, {"id": "57844dd5-801a-4ad1-a85f-aaf71a1d3039", "type": "topic", "title": "Concert Preparation", "description": "Concert readiness combines musical preparation, logistics, psychology, and wellness. Students learn how to move from rehearsal competence to reliable performance.", "children": [{"id": "8b248e4d-4180-4059-a8d5-1ae000ca8e5f", "type": "subtopic", "title": "Practice planning", "children": [{"id": "41237943-f046-47de-98a5-152d4a14b921", "type": "concept", "title": "Long-range planning"}, {"id": "cfab4de8-a487-49f3-921a-ff0f1da3e7f3", "type": "concept", "title": "Hard passage tracking"}, {"id": "18afc8d8-e501-4001-9792-fcb2d0de7b3a", "type": "concept", "title": "Rest and recovery"}], "description": "Students learn to distribute individual work across the rehearsal cycle."}, {"id": "b0d238bd-6b68-4492-b66e-35fc9863e84d", "type": "subtopic", "title": "Dress rehearsal priorities", "children": [{"id": "fb4de07a-58ec-4f89-a0dd-e4a0c61e564f", "type": "concept", "title": "Transitions"}, {"id": "ef02cd07-fa89-4a71-88e3-504c7d83e6e6", "type": "concept", "title": "Stage setup"}, {"id": "c7f1ed63-6b62-4ab3-8529-3cd8b2373ea3", "type": "concept", "title": "Balance and acoustic adjustments"}], "description": "The goal is to use the final rehearsal for integration rather than panic."}, {"id": "fea5ccaf-19f5-47d8-b4c4-f5fefba92d90", "type": "subtopic", "title": "Performance psychology", "children": [{"id": "7d55864c-facb-4298-b510-445fd48fc67d", "type": "concept", "title": "Pre-performance routines"}, {"id": "96b8f0fd-69bc-44ba-b06f-0e1d83d38a8c", "type": "concept", "title": "Attention control"}, {"id": "68a2cca6-17be-4a86-bf37-f966fef5c394", "type": "concept", "title": "Error recovery"}], "description": "Students develop strategies for focus, nerves, and recovery."}, {"id": "24a7d847-90e3-4ab5-9d3e-58fc01c3d329", "type": "subtopic", "title": "Wellness and sustainability", "children": [{"id": "d08bdd4f-9938-45f7-80c4-f0ef2d8f7f65", "type": "concept", "title": "Hearing health"}, {"id": "8a7a5f2c-9f6d-4fa9-b56c-58a1212f1dfc", "type": "concept", "title": "Vocal and physical care"}, {"id": "48a4be95-4f15-40d4-9865-90f4021d01dc", "type": "concept", "title": "Managing fatigue"}], "description": "A world-class ensemble course teaches students to protect the body and mind."}]}, {"id": "1107c525-235b-4f10-914d-73416136e7ca", "type": "topic", "title": "Public Performance", "description": "This section treats performance as communication with an audience and a professional responsibility to the ensemble. Students learn stagecraft, presence, reflection, and growth after the concert.", "children": [{"id": "76d19232-35ba-472d-82f9-ad784fe976f8", "type": "subtopic", "title": "Stage protocol", "children": [{"id": "a2701898-5636-403a-a688-6a6d8b4ea3fd", "type": "concept", "title": "Entrance and exit"}, {"id": "6bd48e7c-d10d-407d-a6e8-79b55a33090e", "type": "concept", "title": "Bows and acknowledgments"}, {"id": "ba7cd48a-9642-4728-9d9d-d91e3c3a84f6", "type": "concept", "title": "Onstage focus"}], "description": "Students learn the public behaviors that frame musical performance."}, {"id": "fcf92f89-a2f1-44a8-8474-3b18e30680a1", "type": "subtopic", "title": "Audience connection", "children": [{"id": "accf8d76-7ad2-4b45-90a3-0e6def1f1e6a", "type": "concept", "title": "Expressive commitment"}, {"id": "83a6e019-8a85-462a-bc4a-36ea3dc99cb0", "type": "concept", "title": "Program context"}, {"id": "86eba096-84d6-44c3-ac1e-8a5ec3557c27", "type": "concept", "title": "Responsiveness to room acoustics"}], "description": "The point is to understand performance as shared attention, not private execution."}, {"id": "b43fcdb9-ec15-445d-8d44-e904729db54d", "type": "subtopic", "title": "Professional recovery", "children": [{"id": "695f35fb-b5a6-4844-8b5b-1ac893734aa8", "type": "concept", "title": "Missed entrances"}, {"id": "4cf75707-9a08-47b6-88fa-c165a6b3a020", "type": "concept", "title": "Page turns and equipment issues"}, {"id": "4d3c5af9-d5c7-42bd-9c0c-e9849f117503", "type": "concept", "title": "Maintaining composure"}], "description": "Even strong performances include surprises. Students learn to keep the performance moving."}, {"id": "faa8f5d7-bc31-4fe4-b091-2ff6ff416785", "type": "subtopic", "title": "Post-performance reflection", "children": [{"id": "746d896c-3297-423e-b726-35627bf43530", "type": "concept", "title": "Self-assessment"}, {"id": "69875098-5eec-4593-b339-ea9ddb294ec3", "type": "concept", "title": "Peer and conductor feedback"}, {"id": "7472ecde-0c36-4df5-9851-c2b92422dcaa", "type": "concept", "title": "Archiving recordings and notes"}], "description": "Students learn to evaluate evidence and convert experience into improvement."}]}], "dbBacked": true}$enspjson$::jsonb,
