values
  ('ab0c11be-a8b1-4df2-a1a6-77afd54bbf31', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', null, 'topic'::public.curated_course_node_type, 'Ensemble Etiquette and Protocol', 'This section establishes ensemble membership as professional practice. Students learn that preparation, reliability, respect, and communication are musical skills, not merely behavioral rules.', 0),
