  ('3c9cad6f-9e0d-4d5c-b4a9-88f93ee57c79', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'f95b4f39-6780-4f4a-9369-a72f29e11654', 'concept'::public.curated_course_node_type, 'Shared responsibility for morale', null, 2),
