  ('0c518f7c-abdb-4636-a2f7-023bcdc13817', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'cfae49b6-0a64-4d39-94b9-7c6fdb02318a', 'concept'::public.curated_course_node_type, 'Two, three, and four patterns', null, 0),
