  ('aa9b9258-7a63-4249-a6fe-cf3e87fcc947', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '9b6e8e00-3f35-4c88-ab9c-9f02565f6f67', 'concept'::public.curated_course_node_type, 'Phrase direction', null, 2),
