  ('b7790821-e795-4af3-9b2c-0ffb14488730', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'e07e4cfa-8f81-4ee3-93d5-068fe0546b3d', 'concept'::public.curated_course_node_type, 'Recovering after missed cues', null, 2),
