  ('a5b6a0b0-5d23-44e7-848f-71a0b6ee0ddb', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '9608d5fa-0e02-440c-a36f-6cc97353686f', 'concept'::public.curated_course_node_type, 'Just intonation tendencies', null, 1),
  ('ef2b37fa-cfbc-4a70-b9bf-35894a7be83c', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '9608d5fa-0e02-440c-a36f-6cc97353686f', 'concept'::public.curated_course_node_type, 'Historical and contemporary practices', null, 2),
  ('0acf3c9c-0557-48ef-91d0-fe897c9a3e42', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', null, 'topic'::public.curated_course_node_type, 'Rhythmic Precision', 'This section develops shared time. Students learn that rhythmic accuracy includes pulse, subdivision, articulation, ensemble releases, groove, and responsiveness.', 4),
  ('705d93a0-51ae-4a67-864e-dc577f54aa5b', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '0acf3c9c-0557-48ef-91d0-fe897c9a3e42', 'subtopic'::public.curated_course_node_type, 'Pulse and subdivision', 'Students strengthen the internal clock needed for ensemble independence.', 0),
  ('e50d564a-ad45-4462-b121-53301c6464d9', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '705d93a0-51ae-4a67-864e-dc577f54aa5b', 'concept'::public.curated_course_node_type, 'Counting systems', null, 0),
  ('35c0034c-3a36-4934-acfb-0bad2c2d69a5', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '705d93a0-51ae-4a67-864e-dc577f54aa5b', 'concept'::public.curated_course_node_type, 'Subdividing rests', null, 1),
  ('7d6330d6-8e80-49ad-9127-46ec54365f20', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '705d93a0-51ae-4a67-864e-dc577f54aa5b', 'concept'::public.curated_course_node_type, 'Tempo stability', null, 2),
  ('99c01774-f630-4fd3-bbff-511c77e69264', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '0acf3c9c-0557-48ef-91d0-fe897c9a3e42', 'subtopic'::public.curated_course_node_type, 'Articulation alignment', 'Rhythm becomes audible through the beginnings, shapes, and ends of notes.', 1),
  ('1df1d84a-dd68-46a4-afe0-2de18d005ffe', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '99c01774-f630-4fd3-bbff-511c77e69264', 'concept'::public.curated_course_node_type, 'Attacks', null, 0),
  ('e9663621-f15c-4d46-826d-b2049f12dace', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '99c01774-f630-4fd3-bbff-511c77e69264', 'concept'::public.curated_course_node_type, 'Note lengths', null, 1),
  ('2bd81d94-37be-4aab-a394-d147798a158d', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '99c01774-f630-4fd3-bbff-511c77e69264', 'concept'::public.curated_course_node_type, 'Releases', null, 2),
  ('d344779f-38a2-4842-a354-fcf18095be8a', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '0acf3c9c-0557-48ef-91d0-fe897c9a3e42', 'subtopic'::public.curated_course_node_type, 'Complex rhythm and meter', 'The goal is to approach challenging notation calmly and systematically.', 2),
  ('180dcb77-7fb0-42ce-9cad-cef9e25c5209', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'd344779f-38a2-4842-a354-fcf18095be8a', 'concept'::public.curated_course_node_type, 'Syncopation', null, 0),
  ('3895de18-f982-44d1-bb18-73f1379321e7', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'd344779f-38a2-4842-a354-fcf18095be8a', 'concept'::public.curated_course_node_type, 'Mixed meter', null, 1);
