  ('29670c73-c950-4242-867c-1423ac1e8dda', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'a0f59024-ae41-4e4f-b923-2583cf510a75', 'concept'::public.curated_course_node_type, 'Swing and backbeat', null, 0),
  ('7deecff6-fcee-43c6-a3ba-ad7d4141f121', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'a0f59024-ae41-4e4f-b923-2583cf510a75', 'concept'::public.curated_course_node_type, 'Dance rhythm', null, 1),
  ('bf8404f3-0792-4e0a-abc0-4c5f80c67802', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'a0f59024-ae41-4e4f-b923-2583cf510a75', 'concept'::public.curated_course_node_type, 'Rubato and flexible time', null, 2),
  ('1d818558-bd1e-4cca-98f8-0fe8e40efd4d', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', null, 'topic'::public.curated_course_node_type, 'Sight-Reading in Ensemble', 'Sight-reading prepares students to function in auditions, rehearsals, church jobs, sessions, and professional ensembles. The emphasis is quick comprehension and reliable recovery.', 5),
  ('5b8b8546-0ce8-4485-aa1b-9f7c9d15b37f', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1d818558-bd1e-4cca-98f8-0fe8e40efd4d', 'subtopic'::public.curated_course_node_type, 'Pre-reading scan', 'Students learn what to notice before the first note.', 0),
  ('0a2ac27c-632e-40f7-b565-5992f3281e50', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '5b8b8546-0ce8-4485-aa1b-9f7c9d15b37f', 'concept'::public.curated_course_node_type, 'Key and meter', null, 0),
  ('4c32b1f7-b379-402f-928e-288ba5afa0bd', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '5b8b8546-0ce8-4485-aa1b-9f7c9d15b37f', 'concept'::public.curated_course_node_type, 'Tempo and style markings', null, 1),
  ('af4ed5f7-ff89-415d-9568-329ae946be4a', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '5b8b8546-0ce8-4485-aa1b-9f7c9d15b37f', 'concept'::public.curated_course_node_type, 'Road maps, repeats, and cues', null, 2),
  ('a261ae7f-0d27-401d-83d2-5734602d839b', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1d818558-bd1e-4cca-98f8-0fe8e40efd4d', 'subtopic'::public.curated_course_node_type, 'Rhythm-first strategies', 'The point is to keep time and form intact even when pitch or detail is imperfect.', 1),
  ('005099f4-8682-4b0c-a65f-0b6bde985ed0', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'a261ae7f-0d27-401d-83d2-5734602d839b', 'concept'::public.curated_course_node_type, 'Counting rests', null, 0),
  ('5aadd46b-16c5-4a7c-8ace-0cef4d0390bc', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'a261ae7f-0d27-401d-83d2-5734602d839b', 'concept'::public.curated_course_node_type, 'Prioritizing entrances', null, 1),
  ('4cacbec9-881a-4fcc-8abe-5e11436941e8', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'a261ae7f-0d27-401d-83d2-5734602d839b', 'concept'::public.curated_course_node_type, 'Maintaining pulse', null, 2),
  ('19870f57-3e4b-432c-afe7-77025a9b2f98', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1d818558-bd1e-4cca-98f8-0fe8e40efd4d', 'subtopic'::public.curated_course_node_type, 'Pitch and pattern recognition', 'Students learn to read in chunks rather than note by note.', 2),
  ('9f05a5fc-4644-4649-97f2-0f229a0cb432', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '19870f57-3e4b-432c-afe7-77025a9b2f98', 'concept'::public.curated_course_node_type, 'Scales and arpeggios', null, 0),
  ('400c5b4c-fbda-4a2c-b830-ef0c02ceeccd', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '19870f57-3e4b-432c-afe7-77025a9b2f98', 'concept'::public.curated_course_node_type, 'Sequences', null, 1),
  ('16fab142-d596-484c-bf8b-7d7e9d672e2c', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '19870f57-3e4b-432c-afe7-77025a9b2f98', 'concept'::public.curated_course_node_type, 'Common harmonic patterns', null, 2),
  ('1020e64c-2132-4ea4-b594-7e851d6e6726', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1d818558-bd1e-4cca-98f8-0fe8e40efd4d', 'subtopic'::public.curated_course_node_type, 'Recovery and ensemble awareness', 'Strong sight-readers recover quickly and stay connected to the group.', 3),
  ('32748fcc-4a7e-4116-82cd-051928be6c5b', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1020e64c-2132-4ea4-b594-7e851d6e6726', 'concept'::public.curated_course_node_type, 'Listening for landmarks', null, 0),
  ('6521c279-b4fb-46a9-92df-45372cc1bdc7', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1020e64c-2132-4ea4-b594-7e851d6e6726', 'concept'::public.curated_course_node_type, 'Re-entering after errors', null, 1),
  ('5cdc7332-0a9e-4df3-b6de-7f87457e3be6', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '1020e64c-2132-4ea4-b594-7e851d6e6726', 'concept'::public.curated_course_node_type, 'Watching conductor and section', null, 2),
  ('179aad3e-f436-4126-be58-5fd72f51146b', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', null, 'topic'::public.curated_course_node_type, 'Sectional Rehearsals', 'Sectionals teach students to diagnose problems and rehearse efficiently without always relying on the conductor. They build leadership, independence, and shared accountability.', 6),
  ('271632ff-0a9f-46cb-bcf3-e289bf03ca80', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '179aad3e-f436-4126-be58-5fd72f51146b', 'subtopic'::public.curated_course_node_type, 'Setting sectional goals', 'Students learn to choose priorities that matter musically and technically.', 0),
  ('076862bc-1094-4f89-8f92-192c9993e395', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '271632ff-0a9f-46cb-bcf3-e289bf03ca80', 'concept'::public.curated_course_node_type, 'Pitch and rhythm targets', null, 0),
  ('b191a4da-95fb-4dfd-9409-8120c8faaf5a', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '271632ff-0a9f-46cb-bcf3-e289bf03ca80', 'concept'::public.curated_course_node_type, 'Balance issues', null, 1),
  ('da1c27a5-d064-4ccb-a651-92286c36929c', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '271632ff-0a9f-46cb-bcf3-e289bf03ca80', 'concept'::public.curated_course_node_type, 'Difficult transitions', null, 2),
  ('d831cbf4-4b3c-4f6d-8c72-4b0c7882ff02', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '179aad3e-f436-4126-be58-5fd72f51146b', 'subtopic'::public.curated_course_node_type, 'Section leadership', 'The goal is to lead peers clearly without turning rehearsal into criticism.', 1),
  ('cc6ebcc4-db18-450f-b1e4-a0f6242d8ac7', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'd831cbf4-4b3c-4f6d-8c72-4b0c7882ff02', 'concept'::public.curated_course_node_type, 'Principal responsibilities', null, 0),
  ('bd1703ae-1143-4cc3-93ee-b71a501fc118', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'd831cbf4-4b3c-4f6d-8c72-4b0c7882ff02', 'concept'::public.curated_course_node_type, 'Constructive language', null, 1),
