  ('992e95e2-7289-49fe-b2fd-0e2588968b1b', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '179aad3e-f436-4126-be58-5fd72f51146b', 'subtopic'::public.curated_course_node_type, 'Rehearsal techniques', 'Students practice tools that make repetition productive.', 2),
  ('bd81a902-4f5e-495c-be45-c9ac5f504778', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '992e95e2-7289-49fe-b2fd-0e2588968b1b', 'concept'::public.curated_course_node_type, 'Slow practice', null, 0),
  ('139931d3-1c55-4325-a41c-9c7110f97a64', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '992e95e2-7289-49fe-b2fd-0e2588968b1b', 'concept'::public.curated_course_node_type, 'Looping small units', null, 1),
