  ('c8e292de-7832-4a93-85a4-35cdae646fa8', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', '179aad3e-f436-4126-be58-5fd72f51146b', 'subtopic'::public.curated_course_node_type, 'Reporting and reintegration', 'Sectional work must return to the full ensemble with clarity.', 3),
  ('8feabae4-8844-457e-ba5d-89bfe615bf0f', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'c8e292de-7832-4a93-85a4-35cdae646fa8', 'concept'::public.curated_course_node_type, 'Marking decisions', null, 0),
  ('d2707e74-8e61-421c-96f5-14f618f2220f', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'c8e292de-7832-4a93-85a4-35cdae646fa8', 'concept'::public.curated_course_node_type, 'Questions for conductor', null, 1),
  ('d7ab9eb4-6b0d-4c54-adae-d4e60f859bcb', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', 'c8e292de-7832-4a93-85a4-35cdae646fa8', 'concept'::public.curated_course_node_type, 'Testing sectional fixes in context', null, 2),
  ('e7eb3d55-9374-4dd3-8f4e-0af8d3c08527', 'f1a2b3c4-5d6e-4f08-9b88-8c9d0e1f2a08', null, 'topic'::public.curated_course_node_type, 'Repertoire Across Styles', 'This section broadens ensemble musicianship beyond one tradition. Students learn how style, history, notation, language, and cultural context shape performance choices.', 7);
